using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace {{Service}}.Api.Data;

/// <summary>
/// Applies EF Core migrations when the service starts. Enabled only with Database:MigrateOnStartup=true
/// (the Aspire AppHost generated by MSG sets it); in production, run migrations in your pipeline instead.
/// With no migrations yet it creates the schema directly, so a brand-new service works on the first run.
/// </summary>
internal sealed class DatabaseMigrator(IServiceProvider services, ILogger<DatabaseMigrator> logger) : IHostedService
{
    public async Task StartAsync(CancellationToken cancellationToken)
    {
        using var scope = services.CreateScope();
        var database = scope.ServiceProvider.GetRequiredService<{{Service}}DbContext>().Database;

        if (database.GetMigrations().Any())
        {
            logger.LogInformation("Applying database migrations");
            await database.MigrateAsync(cancellationToken).ConfigureAwait(false);
        }
        else
        {
            logger.LogWarning("No EF Core migrations found: creating the schema with EnsureCreated (development only). Add one with 'dotnet ef migrations add Initial'");
            await database.EnsureCreatedAsync(cancellationToken).ConfigureAwait(false);
        }
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
